// The editor's banner CSS (resources/js/banner/styles.js) must match the live
// site's (App\Support\Banner\BannerStyles). Both are checked against the same
// fixture, generated by tests/Unit/Banner/BannerStylesTest.php.
// Run with: npm test
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import { setFontStacks, bannerStyle, overlayStyle, backgroundStyle, elementStyle, overlayBackground, num, colorCss } from '../../resources/js/banner/styles.js';

const fixture = JSON.parse(fs.readFileSync(new URL('../fixtures/banner/styles.json', import.meta.url), 'utf8'));
setFontStacks(fixture.fontStacks);

const render = {
    banner: (c) => bannerStyle(c.input),
    overlay: (c) => overlayStyle(c.input),
    background: (c) => backgroundStyle(c.input),
    element: (c) => elementStyle(c.input, c.layer),
    overlayBackground: (c) => overlayBackground(c.input),
};

for (const c of fixture.cases) {
    test(`same CSS as PHP: ${c.name}`, () => {
        assert.equal(render[c.kind](c), c.expected);
    });
}

test('numbers are written like PHP writes them', () => {
    assert.equal(num(12.5), '12.5');
    assert.equal(num(48), '48');
    assert.equal(num(0.9), '0.9');
    assert.equal(num(-0), '0');
    assert.equal(num(1.23456), '1.235');
});

test('transparent colours keep alpha 0', () => {
    assert.equal(colorCss({ r: 46, g: 16, b: 101, a: 0 }), 'rgba(46,16,101,0)');
});

test('an overlay that is off draws nothing', () => {
    assert.equal(overlayBackground({ enabled: false, mode: 'solid', solid: { color: { r: 0, g: 0, b: 0, a: 1 } } }), 'none');
});
